<span class="line"><span style="color:#6F42C1;">ln</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-s</span><span style="color:#24292E;"> </span><span style="color:#032F62;">/yousri/dotnet6.0/dotnet</span><span style="color:#24292E;"> </span><span style="color:#032F62;">/usr/bin/dotnet6.0</span></span>
